import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';

const Dashboard = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [problems, setProblems] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchProblems();
  }, []);

  const fetchProblems = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:5000/api/problems', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProblems(response.data.problems || []);
    } catch (error) {
      console.error('Error fetching problems:', error);
    } finally {
      setLoading(false);
    }
  };

  const totalProblems = problems.length;
  const solved = user?.stats?.problemsSolved || 0;
  const attempts = user?.stats?.totalAttempts || 0;
  const successRate = attempts > 0 ? Math.round((solved / attempts) * 100) : 0;

  return (
    <div style={styles.container}>
      {/* SIDEBAR */}
      <div style={styles.sidebar}>
        <div style={styles.sidebarLogo}>⚡ CodeArena</div>
        <div style={styles.sidebarMenu}>
          <div style={styles.sidebarItemActive}>📊 Dashboard</div>
          <div style={styles.sidebarItem}>📋 Assignments</div>
          <div style={styles.sidebarItem}>✅ Completed Tasks</div>
          <div style={styles.sidebarItem}>🏆 Today's Titans</div>
          <div style={styles.sidebarItem}>📌 More ▼</div>
        </div>
        <div style={styles.sidebarBottom}>
          <div style={styles.userInfo}>
            <span style={styles.userAvatar}>👤</span>
            <span style={styles.userName}>{user?.username || 'User'}</span>
          </div>
        </div>
      </div>

      {/* MAIN CONTENT */}
      <div style={styles.mainContent}>
        {/* STATS ROW */}
        <div style={styles.statsRow}>
          <div style={styles.statItem}>
            <span style={styles.statNumber}>{totalProblems}</span>
            <span style={styles.statLabel}>Total Problems</span>
          </div>
          <div style={styles.statItem}>
            <span style={styles.statNumber}>{solved}</span>
            <span style={styles.statLabel}>Solved</span>
          </div>
          <div style={styles.statItem}>
            <span style={styles.statNumber}>{attempts}</span>
            <span style={styles.statLabel}>Attempts</span>
          </div>
          <div style={styles.statItem}>
            <span style={styles.statNumber}>{successRate}%</span>
            <span style={styles.statLabel}>Success Rate</span>
          </div>
        </div>

        {/* ASSIGNMENTS */}
        <div style={styles.assignmentsSection}>
          <h2 style={styles.sectionTitle}>📋 ASSIGNMENTS</h2>

          <div style={styles.problemGrid}>
            {loading ? (
              <div style={styles.loadingText}>Loading...</div>
            ) : problems.length === 0 ? (
              <div style={styles.emptyState}>No assignments available</div>
            ) : (
              problems.map((problem, index) => (
                <div key={problem._id} style={styles.problemCard}>
                  <div style={styles.programNumber}>PROGRAM-{index + 1}</div>
                  <div style={styles.problemTitle}>{problem.title}</div>
                  <div style={styles.problemMeta}>
                    <span style={styles.problemId}>FS-A1-Audi-2027</span>
                    <span style={styles.problemLab}>LAB</span>
                  </div>
                  <div style={styles.startedInfo}>
                    <span style={styles.startedLabel}>STARTED</span>
                    <span style={styles.startedDate}>
                      on {new Date(problem.createdAt).toLocaleDateString('en-US', {
                        weekday: 'long',
                        day: 'numeric',
                        month: 'long',
                        year: 'numeric',
                      })}
                    </span>
                  </div>
                  <div style={styles.difficultyRow}>
                    <span
                      style={{
                        ...styles.difficultyBadge,
                        background:
                          problem.difficulty === 'Easy'
                            ? '#28a745'
                            : problem.difficulty === 'Medium'
                            ? '#ffc107'
                            : '#dc3545',
                        color: problem.difficulty === 'Medium' ? '#333' : 'white',
                      }}
                    >
                      {problem.difficulty || 'Easy'}
                    </span>
                  </div>
                  <button
                    style={styles.attemptBtn}
                    onClick={() => navigate(`/problems/${problem._id}`)}
                  >
                    ATTEMPT →
                  </button>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: {
    display: 'flex',
    minHeight: '100vh',
    background: '#f0f2f5',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },

  // SIDEBAR
  sidebar: {
    width: '220px',
    background: '#16213e',
    color: '#ffffff',
    padding: '24px 16px',
    display: 'flex',
    flexDirection: 'column',
    position: 'fixed',
    height: '100vh',
    boxShadow: '2px 0 20px rgba(0,0,0,0.15)',
    zIndex: 100,
  },
  sidebarLogo: {
    fontSize: '20px',
    fontWeight: 700,
    padding: '0 12px 25px 12px',
    borderBottom: '1px solid rgba(255,255,255,0.08)',
    marginBottom: '16px',
    color: '#ffffff',
  },
  sidebarMenu: {
    display: 'flex',
    flexDirection: 'column',
    gap: '2px',
    flex: 1,
  },
  sidebarItem: {
    padding: '10px 14px',
    borderRadius: '8px',
    cursor: 'pointer',
    fontSize: '14px',
    fontWeight: 500,
    color: 'rgba(255,255,255,0.5)',
    transition: 'all 0.2s',
  },
  sidebarItemActive: {
    padding: '10px 14px',
    borderRadius: '8px',
    cursor: 'pointer',
    fontSize: '14px',
    fontWeight: 600,
    color: '#ffffff',
    background: 'rgba(108, 99, 255, 0.2)',
  },
  sidebarBottom: {
    borderTop: '1px solid rgba(255,255,255,0.08)',
    paddingTop: '16px',
  },
  userInfo: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    padding: '8px 12px',
    borderRadius: '8px',
